//===- mac_sparse.cc --------------------------------------------*- C++ -*-===//
//
// rand capture kernel for sparse MAC config mode (2, 3, 2) `4x16_16x4`
// (GENERATED by tools/gen_mac_sparse.py). Per tile and signedness flavour it builds the sparse B operand with update() from a stored-data block and a mask block,
// then runs mul, mac, msc.
// Chunk layout: 9 operand blocks of T tiles (A0 D0 M0 A1 D1 M1 A2 D2 M2).
//
//===----------------------------------------------------------------------===//

#include <stdint.h>

// Peano builds see no Chess-side define; the stream/ADF half of aie_api is not needed.
#ifndef __AIE_API_AIE_ADF_HPP__
#define __AIE_API_AIE_ADF_HPP__
#endif
#include <aie_api/aie.hpp>

#define T 16
#define OUT_WORDS_PER_TILE 48

#define STORE(r, dst) \
  do { aie::accum<accfloat, 16> w(r); aie::store_v((float *)(dst), w.to_vector<float>()); } while (0)

extern "C" {

void mac_sparse(uint8_t *restrict in, int32_t *restrict out) {
  uint8_t *in0 = in + 0;
  uint8_t *in1 = in + 0 + T * 128;
  uint8_t *in2 = in + 0 + T * 128 + T * 64;
  uint8_t *in3 = in + 0 + T * 128 + T * 64 + T * 16;
  uint8_t *in4 = in + 0 + T * 128 + T * 64 + T * 16 + T * 128;
  uint8_t *in5 = in + 0 + T * 128 + T * 64 + T * 16 + T * 128 + T * 64;
  uint8_t *in6 = in + 0 + T * 128 + T * 64 + T * 16 + T * 128 + T * 64 + T * 16;
  uint8_t *in7 = in + 0 + T * 128 + T * 64 + T * 16 + T * 128 + T * 64 + T * 16 + T * 128;
  uint8_t *in8 = in + 0 + T * 128 + T * 64 + T * 16 + T * 128 + T * 64 + T * 16 + T * 128 + T * 64;
  event0();
  for (int n = 0; n < T; n++) {
    int32_t *o = out + n * OUT_WORDS_PER_TILE;
    { // bf
      v64bfloat16 a0 = *(v64bfloat16 *)(in0 + n * 128);
      v32bfloat16 d0 = *(v32bfloat16 *)(in1 + n * 64);
      sparsity_t m0 = *(sparsity_t *)(in2 + n * 16);
      v64bfloat16_sparse b0;
      b0 = update(b0, d0);
      b0 = update(b0, m0);
      v64bfloat16 a1 = *(v64bfloat16 *)(in3 + n * 128);
      v32bfloat16 d1 = *(v32bfloat16 *)(in4 + n * 64);
      sparsity_t m1 = *(sparsity_t *)(in5 + n * 16);
      v64bfloat16_sparse b1;
      b1 = update(b1, d1);
      b1 = update(b1, m1);
      v64bfloat16 a2 = *(v64bfloat16 *)(in6 + n * 128);
      v32bfloat16 d2 = *(v32bfloat16 *)(in7 + n * 64);
      sparsity_t m2 = *(sparsity_t *)(in8 + n * 16);
      v64bfloat16_sparse b2;
      b2 = update(b2, d2);
      b2 = update(b2, m2);
      v16accfloat r0 = mul_4x16_16x4(a0, b0);
      v16accfloat r1 = mac_4x16_16x4(a1, b1, r0);
      v16accfloat r2 = msc_4x16_16x4(a2, b2, r1);
      STORE(r0, o + 0);
      STORE(r1, o + 16);
      STORE(r2, o + 32);
    }
  }
  event1();
}

} // extern "C"
